package com.ftk.tpip.control.api.catalog;
import com.ftk.tpip.catalog.domain.model.*;import com.ftk.tpip.control.application.catalog.CatalogHierarchyApplicationService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.URI;import java.time.Instant;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/domains") public class BusinessDomainController{private final CatalogHierarchyApplicationService s;public BusinessDomainController(CatalogHierarchyApplicationService s){this.s=s;}
@PostMapping public ResponseEntity<Response> create(@Valid @RequestBody Create r,@RequestHeader("X-Operator") @NotBlank @Size(max=100) String a){var d=s.createDomain(r.domainCode,r.domainName,r.description,r.ownerCode,a);return ResponseEntity.created(URI.create("/control/v1/domains/"+d.id())).body(Response.from(d));}@GetMapping("/{id}") public Response get(@PathVariable @Min(1)long id){return Response.from(s.getDomain(id));}@GetMapping public Page list(@RequestParam(required=false)String keyword,@RequestParam(required=false)CatalogAssetStatus status,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(200)int size){var p=s.domains(keyword,status,page,size);return new Page(p.items().stream().map(Response::from).toList(),page,size,p.totalElements());}@PutMapping("/{id}")public Response update(@PathVariable @Min(1)long id,@Valid @RequestBody Update r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String a){return Response.from(s.updateDomain(id,r.domainName,r.description,r.ownerCode,r.status,r.rowVersion,a));}
public record Create(@NotBlank@Size(max=100)@Pattern(regexp="^[a-z][a-z0-9]*(?:[._-][a-z0-9]+)*$")String domainCode,@NotBlank@Size(max=200)String domainName,@Size(max=1000)String description,@NotBlank@Size(max=100)String ownerCode){}public record Update(@NotBlank@Size(max=200)String domainName,@Size(max=1000)String description,@NotBlank@Size(max=100)String ownerCode,@NotNull CatalogAssetStatus status,@PositiveOrZero long rowVersion){}public record Response(long id,String domainCode,String domainName,String description,String ownerCode,CatalogAssetStatus status,long rowVersion,Instant createdAt,Instant updatedAt){static Response from(BusinessDomain d){return new Response(d.id(),d.domainCode().value(),d.domainName(),d.description(),d.ownerCode(),d.status(),d.rowVersion(),d.createdAt(),d.updatedAt());}}public record Page(List<Response>items,int page,int size,long totalElements){}
}
